-- VibeTradez local development seed data
--
-- AUTO-GENERATED by generate-seed.py — do not hand-edit. Re-run that
-- script to refresh; the random seed is fixed so output is stable.
--
-- Contains a year of realistic equity-walk auto-execution history
-- plus today's pre-EOD state (three live holdings, no summaries yet)
-- so the dashboard, history, and trade-detail pages all render
-- meaningful data on a fresh local boot.

-- ─── Schema (mirrors internal/store/store.go migrate()) ──────────────────

CREATE TABLE IF NOT EXISTS trades (
    id SERIAL PRIMARY KEY,
    date TEXT NOT NULL,
    symbol TEXT NOT NULL,
    contract_type TEXT NOT NULL,
    strike_price DOUBLE PRECISION NOT NULL,
    expiration TEXT NOT NULL,
    dte INTEGER NOT NULL,
    estimated_price DOUBLE PRECISION NOT NULL,
    thesis TEXT NOT NULL DEFAULT '',
    sentiment_score DOUBLE PRECISION NOT NULL DEFAULT 0,
    current_price DOUBLE PRECISION NOT NULL DEFAULT 0,
    target_price DOUBLE PRECISION NOT NULL DEFAULT 0,
    stop_loss DOUBLE PRECISION NOT NULL DEFAULT 0,
    risk_level TEXT NOT NULL DEFAULT '',
    catalyst TEXT NOT NULL DEFAULT '',
    mention_count INTEGER NOT NULL DEFAULT 0,
    rank INTEGER NOT NULL DEFAULT 0,
    score INTEGER NOT NULL DEFAULT 0,
    rationale TEXT NOT NULL DEFAULT '',
    model TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_trades_date ON trades(date);

CREATE TABLE IF NOT EXISTS summaries (
    id SERIAL PRIMARY KEY,
    date TEXT NOT NULL,
    symbol TEXT NOT NULL,
    contract_type TEXT NOT NULL,
    strike_price DOUBLE PRECISION NOT NULL,
    expiration TEXT NOT NULL,
    entry_price DOUBLE PRECISION NOT NULL,
    closing_price DOUBLE PRECISION NOT NULL,
    stock_open DOUBLE PRECISION NOT NULL,
    stock_close DOUBLE PRECISION NOT NULL,
    notes TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_summaries_date ON summaries(date);

CREATE TABLE IF NOT EXISTS executions (
    id SERIAL PRIMARY KEY,
    trade_id INTEGER REFERENCES trades(id),
    mode TEXT NOT NULL,
    side TEXT NOT NULL,
    schwab_order_id TEXT,
    status TEXT NOT NULL,
    fill_price DOUBLE PRECISION,
    filled_quantity INTEGER NOT NULL DEFAULT 0,
    requested_quantity INTEGER NOT NULL,
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    filled_at TIMESTAMPTZ,
    error_message TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_executions_trade_id ON executions(trade_id);
CREATE INDEX IF NOT EXISTS idx_executions_open_pending
    ON executions(status) WHERE status IN ('pending','working');

CREATE TABLE IF NOT EXISTS subscribers (
    id SERIAL PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL DEFAULT '',
    active BOOLEAN NOT NULL DEFAULT true,
    auth_user_id BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    unsubscribed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_subscribers_active ON subscribers(active);
CREATE INDEX IF NOT EXISTS idx_subscribers_auth_user_id ON subscribers(auth_user_id);

CREATE TABLE IF NOT EXISTS oauth_tokens (
    id SERIAL PRIMARY KEY,
    provider TEXT NOT NULL UNIQUE,
    access_token TEXT NOT NULL,
    refresh_token TEXT NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    refresh_token_issued_at TIMESTAMPTZ,
    reauth_nag_sent_on DATE,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sent_rollouts (
    slug TEXT PRIMARY KEY,
    sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    recipient_count INTEGER NOT NULL
);

TRUNCATE trades, summaries, executions, subscribers, sent_rollouts RESTART IDENTITY;


